'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,cents} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import type {PaymentScope} from '@/lib/billing-payment-entry';
import {billingDollars} from './billing-accounts';
export type BillingPostingDraft=PaymentScope&{payment:string;clearing:string;allocations:{account_id:string;amount_minor:string}[];period:string;date:string;description:string;review:Record<string,unknown>;accountLabels?:Record<string,string>};
type Props=PaymentScope&{payment:{payment_id:string;kind:string;amount_minor:string};onReview:(draft:BillingPostingDraft)=>void;onBusyChange?:(busy:boolean)=>void};
export function BillingPostingReview(props:Props){return <Review key={[props.actor,props.tenant,props.property,props.account,props.payment.payment_id].join('/')} {...props}/>}
function Review(props:Props){
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[clearing,setClearing]=useState(''),[control,setControl]=useState(''),[period,setPeriod]=useState(''),[date,setDate]=useState(''),[description,setDescription]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const [splits,setSplits]=useState<{id:string;account:string;amount:string}[]>([]);
 const lock=useRef(false),alive=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);useEffect(()=>{props.onBusyChange?.(busy);return()=>props.onBusyChange?.(false)},[busy,props.onBusyChange]);
 async function run(action:()=>Promise<void>){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await action()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to review posting.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function load(){setSetup(null);setSplits([]);setClearing('');setControl('');setPeriod('');setDate('');const result=readAccountingSetup(await hotelRpc('gl_setup',{p_tenant:props.tenant,p_property:props.property}),props.tenant,props.property);if(alive.current)setSetup(result)}
 async function review(){const p=setup?.periods.find(x=>x.period_id===period),a=setup?.accounts.find(x=>x.account_id===clearing),b=setup?.accounts.find(x=>x.account_id===control);if(!p||p.closed||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date||date<p.start_date||date>=p.end_date_exclusive||!a?.active||a.kind!=='asset'||!b?.active||!['asset','liability'].includes(b.kind)||clearing===control||description.trim().length<4||description.trim().length>500)throw Error('Select distinct active accounts, an open period, a date within it, and a posting description.');
  const extra=splits.map(s=>({account_id:s.account,amount_minor:String(cents(s.amount))}));const remaining=BigInt(props.payment.amount_minor)-extra.reduce((sum,s)=>sum+BigInt(s.amount_minor),0n);const seen=new Set([clearing,control]);for(const row of extra){const account=setup?.accounts.find(a=>a.account_id===row.account_id);if(!account?.active||!['asset','liability'].includes(account.kind)||seen.has(row.account_id)||BigInt(row.amount_minor)<=0n)throw Error('Choose distinct active accounts and positive split amounts.');seen.add(row.account_id)}if(remaining<=0n)throw Error('Split amounts must leave a positive amount for the primary account.');const allocations=[{account_id:control,amount_minor:remaining.toString()},...extra];const v=await hotelRpc<Record<string,unknown>>('billing_posting_review',{p_tenant:props.tenant,p_property:props.property,p_account:props.account,p_payment:props.payment.payment_id,p_clearing:clearing,p_allocations:allocations});
  const incoming=props.payment.kind==='external_payment';const lines=v?.lines as {account_id:string;side:string;amount_minor:string}[];
  if(!v||v.tenant_id!==props.tenant||v.property_id!==props.property||v.account_id!==props.account||v.payment_id!==props.payment.payment_id||v.currency!=='USD'||v.source_kind!=='billing_account_payment'||v.source_version!==1||v.payment_kind!==props.payment.kind||v.amount_minor!==props.payment.amount_minor||v.posted!==false||!Array.isArray(lines)||lines.length!==allocations.length+1||lines[0].account_id!==clearing||lines[0].side!==(incoming?'debit':'credit')||lines[0].amount_minor!==props.payment.amount_minor||allocations.some((a,i)=>lines[i+1]?.account_id!==a.account_id||lines[i+1]?.side!==(incoming?'credit':'debit')||lines[i+1]?.amount_minor!==a.amount_minor))throw Error('Ledger preview does not match the selected payment and accounts.');
  if(alive.current)props.onReview({actor:props.actor,tenant:props.tenant,property:props.property,account:props.account,payment:props.payment.payment_id,clearing,allocations,period,date,description:description.trim(),review:v,accountLabels:Object.fromEntries((setup?.accounts??[]).filter(x=>seen.has(x.account_id)).map(x=>[x.account_id,x.code+' · '+x.name]))});
 }
 return <section className="pilot-settings"><h3>Review ledger posting</h3><p>{billingDollars(props.payment.amount_minor)} · {props.payment.kind==='external_payment'?'Receipt':'Refund / correction'}</p>{error&&<p role="alert">{error}</p>}<fieldset disabled={busy} style={{border:0,padding:0,margin:0}}><button className="secondary" onClick={()=>void run(load)}>Load accounting accounts</button>{setup&&<><label className="field">Cash / clearing account<select value={clearing} onChange={e=>setClearing(e.target.value)}><option value="">Select account</option>{setup.accounts.filter(a=>a.active&&a.kind==='asset').map(a=><option key={a.account_id} value={a.account_id}>{a.code} · {a.name}</option>)}</select></label><label className="field">Receivable / advance account<select value={control} onChange={e=>setControl(e.target.value)}><option value="">Select account</option>{setup.accounts.filter(a=>a.active&&['asset','liability'].includes(a.kind)&&a.account_id!==clearing).map(a=><option key={a.account_id} value={a.account_id}>{a.code} · {a.name}</option>)}</select></label><p>The primary receivable / advance account receives the amount remaining after any splits.</p>{splits.map((row,index)=><div key={row.id}><label className="field">Split account {index+1}<select value={row.account} onChange={e=>setSplits(splits.map(s=>s.id===row.id?{...s,account:e.target.value}:s))}><option value="">Select account</option>{setup.accounts.filter(a=>a.active&&['asset','liability'].includes(a.kind)&&a.account_id!==clearing&&a.account_id!==control).map(a=><option key={a.account_id} value={a.account_id}>{a.code} · {a.name}</option>)}</select></label><label className="field">Split amount {index+1} (USD)<input inputMode="decimal" value={row.amount} onChange={e=>setSplits(splits.map(s=>s.id===row.id?{...s,amount:e.target.value}:s))}/></label><button className="secondary" onClick={()=>setSplits(splits.filter(s=>s.id!==row.id))}>Remove split {index+1}</button></div>)}<button className="secondary" disabled={splits.length>=19} onClick={()=>setSplits([...splits,{id:crypto.randomUUID(),account:'',amount:''}])}>Add split account</button><label className="field">Open accounting period<select value={period} onChange={e=>setPeriod(e.target.value)}><option value="">Select period</option>{setup.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to {p.end_date_exclusive} (exclusive)</option>)}</select></label><label className="field">Posting date<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label className="field">Posting description<input maxLength={500} value={description} onChange={e=>setDescription(e.target.value)}/></label><button className="primary" onClick={()=>void run(review)}>Review ledger entries</button></>}</fieldset></section>;
}
